//! `shared/units.ts`: the `Units` namespace. The group and struct tables come
//! from `units::tables`, generated by `cargo xtask tables units` from the
//! upstream file so the conversion factors keep their TS expressions (and
//! therefore their exact f64 values). `ALL_UNITS`, `GROUP_BY_UNIT` and
//! `UNIT_SUFFIXES` are derived here exactly as upstream's module IIFEs do:
//! ordered maps where reassigning a key overwrites its value but keeps its
//! first insertion position.

mod tables;

use std::sync::OnceLock;

use asrs_js::string::JsString;

use crate::line_graph_filter::LineGraphFilter;
use crate::util;

/// `Units.UnitConfig`: the conversion factor from the group's base unit, the
/// display suffix and the name variants `UNIT_SUFFIXES` is built from.
#[derive(Clone, Copy, Debug)]
pub struct UnitConfig {
    pub value: f64,
    pub suffix: &'static str,
    pub pluralize_suffix: bool,
    pub names: &'static [&'static str],
}

pub use tables::{STRUCT_UNITS, UNIT_GROUPS};

/// The `Units.convert` error: upstream throws the string
/// `"Invalid unit provided"`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct InvalidUnit;

/// `Units.UnitConversionPreset`, persisted in layouts and preferences.
#[derive(Clone, Debug, PartialEq)]
pub struct UnitConversionPreset {
    /// `string | null` in JS: `None` is `null` (no unit type). A missing
    /// `type` property (`undefined`) is only distinguishable through the
    /// JS-semantics `convert_with_preset`.
    pub r#type: Option<String>,
    pub from: Option<String>,
    pub to: Option<String>,
    pub factor: f64,
}

impl UnitConversionPreset {
    /// `Units.NoopUnitConversion` (`{type: null, factor: 1}`).
    pub fn noop() -> Self {
        Self {
            r#type: None,
            from: None,
            to: None,
            factor: 1.0,
        }
    }

    /// `Units.convertWithPreset`.
    pub fn convert(&self, value: f64) -> Result<f64, InvalidUnit> {
        convert_with_preset(
            value,
            self.r#type.is_none(),
            preset_field(&self.from),
            preset_field(&self.to),
            self.factor,
        )
    }
}

fn preset_field(name: &Option<String>) -> Option<(&str, TempUnit)> {
    name.as_deref().map(|key| (key, TempUnit::for_str(key)))
}

/// `Units.UIUnitOptions`.
#[derive(Clone, Debug, PartialEq)]
pub struct UIUnitOptions {
    pub auto_target: Option<String>,
    pub preset: Option<UnitConversionPreset>,
}

pub const MAX_RECENT_UNITS: usize = 5;

/// `Units.ALL_UNITS` = `Object.assign({}, ...Object.values(UNIT_GROUPS))`:
/// every unit in group order. Object.assign keeps a repeated key's first
/// position with its new value; no unit key repeats across groups.
pub fn all_units() -> &'static [(&'static str, &'static UnitConfig)] {
    static ALL_UNITS: OnceLock<Vec<(&'static str, &'static UnitConfig)>> = OnceLock::new();
    ALL_UNITS.get_or_init(|| {
        let mut all: Vec<(&'static str, &'static UnitConfig)> = Vec::new();
        for (_, units) in UNIT_GROUPS {
            for (key, config) in *units {
                match all.iter_mut().find(|(k, _)| *k == *key) {
                    Some(slot) => slot.1 = config,
                    None => all.push((key, config)),
                }
            }
        }
        all
    })
}

/// `Units.GROUP_BY_UNIT[unit]`.
pub fn group_by_unit(unit: &str) -> Option<&'static str> {
    static GROUP_BY_UNIT: OnceLock<Vec<(&'static str, &'static str)>> = OnceLock::new();
    GROUP_BY_UNIT
        .get_or_init(|| {
            let mut map: Vec<(&'static str, &'static str)> = Vec::new();
            for (group, units) in UNIT_GROUPS {
                for (key, _) in *units {
                    match map.iter_mut().find(|(k, _)| *k == *key) {
                        Some(slot) => slot.1 = group,
                        None => map.push((key, group)),
                    }
                }
            }
            map
        })
        .iter()
        .find(|(k, _)| *k == unit)
        .map(|(_, group)| *group)
}

/// `Units.STRUCT_UNITS[structType][childKey]`.
pub fn struct_unit(struct_type: &str, child_key: &str) -> Option<&'static str> {
    STRUCT_UNITS
        .iter()
        .find(|(ty, _)| *ty == struct_type)?
        .1
        .iter()
        .find(|(k, _)| *k == child_key)
        .map(|(_, unit)| *unit)
}

/// Whether `name` resolves a property through a plain object's prototype
/// chain (`"constructor" in {}` and friends). `Units.convert`'s
/// `from in ALL_UNITS` passes for these and then reads `undefined.value`.
pub fn is_object_proto_name(name: &str) -> bool {
    const PROTO_NAMES: [&str; 12] = [
        "__proto__",
        "constructor",
        "hasOwnProperty",
        "isPrototypeOf",
        "propertyIsEnumerable",
        "toLocaleString",
        "toString",
        "valueOf",
        "__defineGetter__",
        "__defineSetter__",
        "__lookupGetter__",
        "__lookupSetter__",
    ];
    PROTO_NAMES.contains(&name)
}

fn in_all_units(name: &str) -> bool {
    all_units().iter().any(|(k, _)| *k == name) || is_object_proto_name(name)
}

/// `Units.convert`'s `!(from in ALL_UNITS && to in ALL_UNITS)` gate.
pub fn valid_unit_pair(from: &str, to: &str) -> bool {
    in_all_units(from) && in_all_units(to)
}

/// `ALL_UNITS[name].value`: `undefined` for prototype names, which the
/// arithmetic turns into NaN.
fn unit_value(name: &str) -> f64 {
    all_units()
        .iter()
        .find(|(k, _)| *k == name)
        .map_or(f64::NAN, |(_, c)| c.value)
}

/// The temperature special cases `Units.convert` applies to an argument.
/// Upstream compares `from === "fahrenheit"` (strict), `from == "kelvin"`
/// (loose) and `to === "fahrenheit"` / `to === "kelvin"` (both strict): a
/// boxed `"kelvin"` counts as kelvin on the way in but not on the way out.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum TempUnit {
    None,
    Fahrenheit,
    Kelvin,
}

/// `Units.convert`. `from`/`to` are the arguments as property keys and
/// `from_temp`/`to_temp` are the result of the `=== "fahrenheit"` /
/// `== "kelvin"` checks on the raw argument; a boxed string loses `===` but
/// still loose-equals `"kelvin"`. Plain string arguments use `convert`.
pub fn convert_with_temp(
    value: f64,
    from: &str,
    to: &str,
    from_temp: TempUnit,
    to_temp: TempUnit,
) -> Result<f64, InvalidUnit> {
    if !(in_all_units(from) && in_all_units(to)) {
        return Err(InvalidUnit);
    }
    let standard = match from_temp {
        TempUnit::Fahrenheit => (value - 32.0) / 1.8,
        TempUnit::Kelvin => value - 273.15,
        TempUnit::None => value / unit_value(from),
    };
    Ok(match to_temp {
        TempUnit::Fahrenheit => standard * 1.8 + 32.0,
        TempUnit::Kelvin => standard + 273.15,
        TempUnit::None => standard * unit_value(to),
    })
}

/// `Units.convert` for plain string unit names.
pub fn convert(value: f64, from: &str, to: &str) -> Result<f64, InvalidUnit> {
    convert_with_temp(
        value,
        from,
        to,
        TempUnit::for_str(from),
        TempUnit::for_str(to),
    )
}

impl TempUnit {
    fn for_str(name: &str) -> Self {
        match name {
            "fahrenheit" => Self::Fahrenheit,
            "kelvin" => Self::Kelvin,
            _ => Self::None,
        }
    }

    /// `from === "fahrenheit"` (strict) / `from == "kelvin"` (loose):
    /// `primitive` is whether the argument is a primitive string. A boxed
    /// `"fahrenheit"` loses the strict check but `"kelvin"` survives loose.
    pub fn from_arg(key: &str, primitive: bool) -> Self {
        if primitive {
            Self::for_str(key)
        } else if key == "kelvin" {
            Self::Kelvin
        } else {
            Self::None
        }
    }

    /// `to === "fahrenheit"` / `to === "kelvin"`: both strict, so a
    /// non-primitive `to` always falls through to the factor path.
    pub fn to_arg(key: &str, primitive: bool) -> Self {
        if primitive {
            Self::for_str(key)
        } else {
            Self::None
        }
    }
}

/// `Units.convertWithPreset`. `type_is_null` is `preset.type === null` (an
/// `undefined` type is not null); `from`/`to` are `None` only when the
/// property is `undefined`, and otherwise pair the coerced property key with
/// its `TempUnit` special-case flag. `factor` is `preset.factor` after
/// `ToNumber`.
pub fn convert_with_preset(
    value: f64,
    type_is_null: bool,
    from: Option<(&str, TempUnit)>,
    to: Option<(&str, TempUnit)>,
    factor: f64,
) -> Result<f64, InvalidUnit> {
    if type_is_null && factor == 1.0 {
        return Ok(value);
    }
    match (from, to) {
        (Some((from, from_temp)), Some((to, to_temp))) => {
            Ok(convert_with_temp(value, from, to, from_temp, to_temp)? * factor)
        }
        _ => Ok(value * factor),
    }
}

/// `Units.getSuffixForFilter`.
pub fn get_suffix_for_filter(suffix: &JsString, filter: LineGraphFilter) -> JsString {
    let units = suffix.units();
    match filter {
        LineGraphFilter::Differentiate => {
            if suffix.ends_with(&"²".into(), None) {
                let mut out = JsString::from_units(units[..units.len() - 1].to_vec());
                out.push_str(&"³".into());
                out
            } else if suffix.ends_with(&"ps".into(), None) || suffix.ends_with(&"/s".into(), None) {
                let mut out = suffix.clone();
                out.push_str(&"²".into());
                out
            } else {
                let mut out = suffix.clone();
                out.push_str(&"/s".into());
                out
            }
        }
        LineGraphFilter::Integrate => {
            if suffix.ends_with(&"²".into(), None) {
                JsString::from_units(units[..units.len() - 1].to_vec())
            } else if suffix.ends_with(&"/s".into(), None) {
                JsString::from_units(units[..units.len() - 2].to_vec())
            } else {
                let mut out = suffix.clone();
                out.push_str(&"·s".into());
                out
            }
        }
        LineGraphFilter::None => suffix.clone(),
    }
}

/// One `UNIT_SUFFIXES` entry, in JS insertion order, with the derived values
/// `getUnitForField` reads precomputed.
struct UnitSuffix {
    key: JsString,
    lowercase: JsString,
    slash_lowercase: JsString,
    unit: &'static str,
    has_slash: bool,
    separated: bool,
}

fn insert_suffix(map: &mut Vec<UnitSuffix>, key: Vec<u16>, unit: &'static str) {
    let key = JsString::from_units(key);
    if let Some(entry) = map.iter_mut().find(|e| e.key == key) {
        entry.unit = unit;
        return;
    }
    let lowercase = key.to_lower_case();
    let mut slash = JsString::from("/");
    slash.push_str(&lowercase);
    let first = key.units().first().copied().unwrap_or(0);
    map.push(UnitSuffix {
        has_slash: key.units().contains(&u16::from(b'/')),
        separated: first == u16::from(b'_') || first == u16::from(b' '),
        slash_lowercase: slash,
        lowercase,
        key,
        unit,
    });
}

fn without_spaces(units: &[u16]) -> Vec<u16> {
    units
        .iter()
        .copied()
        .filter(|u| *u != u16::from(b' '))
        .collect()
}

fn underscored(units: &[u16]) -> Vec<u16> {
    units
        .iter()
        .map(|u| {
            if *u == u16::from(b' ') {
                u16::from(b'_')
            } else {
                *u
            }
        })
        .collect()
}

fn contains(units: &[u16], needle: &[u16]) -> bool {
    !needle.is_empty() && units.windows(needle.len()).any(|w| w == needle)
}

fn replace_all(units: &[u16], needle: &[u16], with: &[u16]) -> Vec<u16> {
    let mut out = Vec::with_capacity(units.len());
    let mut i = 0;
    while i < units.len() {
        if units[i..].starts_with(needle) {
            out.extend_from_slice(with);
            i += needle.len();
        } else {
            out.push(units[i]);
            i += 1;
        }
    }
    out
}

/// `Units.UNIT_SUFFIXES`: every name variant to its unit key, built by the
/// same IIFE upstream runs at module load.
fn unit_suffixes() -> &'static [UnitSuffix] {
    static UNIT_SUFFIXES: OnceLock<Vec<UnitSuffix>> = OnceLock::new();
    UNIT_SUFFIXES.get_or_init(|| {
        let mut map = Vec::new();
        let space = &[u16::from(b' ')];
        let per = " per ".encode_utf16().collect::<Vec<u16>>();
        let slash = &[u16::from(b'/')];
        for (unit, config) in all_units() {
            for name in config.names {
                let name: Vec<u16> = name.encode_utf16().collect();
                if name.is_empty() {
                    continue;
                }
                let mut prefixed = Vec::with_capacity(name.len() + 1);
                insert_suffix(&mut map, name.clone(), unit);
                prefixed.extend_from_slice(space);
                prefixed.extend_from_slice(&name);
                insert_suffix(&mut map, prefixed.clone(), unit);
                prefixed[0] = u16::from(b'_');
                insert_suffix(&mut map, prefixed, unit);
                if contains(&name, space) {
                    insert_suffix(&mut map, without_spaces(&name), unit);
                    insert_suffix(&mut map, underscored(&name), unit);
                }
                if contains(&name, &per) {
                    let slashed = replace_all(&name, &per, slash);
                    insert_suffix(&mut map, slashed.clone(), unit);
                    insert_suffix(&mut map, without_spaces(&slashed), unit);
                    insert_suffix(&mut map, underscored(&slashed), unit);
                }
            }
        }
        map
    })
}

/// `Units.UNIT_SUFFIXES` in `Object.keys` order (insertion order; no key is
/// a canonical array index).
pub fn unit_suffix_entries() -> impl Iterator<Item = (&'static JsString, &'static str)> {
    unit_suffixes().iter().map(|e| (&e.key, e.unit))
}

/// `Units.UNIT_SUFFIXES[key]` (`key in UNIT_SUFFIXES` first). Only own
/// properties resolve to a unit; prototype names are `None` here.
pub fn unit_suffix(key: &JsString) -> Option<&'static str> {
    unit_suffixes()
        .iter()
        .find(|e| e.key == *key)
        .map(|e| e.unit)
}

/// `Units.getUnitForField`.
pub fn get_unit_for_field(field_key: &JsString) -> Option<&'static str> {
    let lowercase = field_key.to_lower_case();
    let mut matched: Vec<&UnitSuffix> = Vec::new();
    let mut max_len = 0usize;
    for suffix in unit_suffixes() {
        if !suffix.has_slash
            && field_key.len() > suffix.key.len()
            && lowercase.ends_with(&suffix.lowercase, None)
            && !lowercase.ends_with(&suffix.slash_lowercase, None)
            && (suffix.separated
                || util::char_is_capital(field_key, (field_key.len() - suffix.key.len()) as f64))
        {
            matched.push(suffix);
            max_len = max_len.max(suffix.key.len());
        }
    }
    if matched.is_empty() {
        return None;
    }
    let mut best: Option<&UnitSuffix> = None;
    let mut best_chars = 0usize;
    for suffix in matched.iter().filter(|s| s.key.len() == max_len) {
        let start = field_key.len() - suffix.key.len();
        let mut chars = 0;
        for (j, &unit) in suffix.key.units().iter().enumerate() {
            if field_key.units()[start + j] == unit {
                chars += 1;
            }
        }
        if best.is_none() || chars > best_chars {
            best = Some(*suffix);
            best_chars = chars;
        }
    }
    best.map(|s| s.unit)
}
